INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$09f9edb0$SATQ$, $SATQ$35e63faf-cd1e-42e6-b544-7bf3b48941eb$SATQ$::uuid, $SATQ$d38b72e5-b606-432e-bd49-de10ee8e4a64$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In the 1980s, many musicians and journalists in the English-speaking world began to draw attention to music from around the globe&mdash;such as mbaqanga from South Africa and quan họ from Vietnam&mdash;that can&rsquo;t be easily categorized according to British or North American popular music genres, typically referring to such music as &ldquo;world music.&rdquo; While some scholars have welcomed this development for bringing diverse musical forms to prominence in countries where they&rsquo;d previously been overlooked, musicologist Su Zheng claims that the concept of world music homogenizes highly distinct traditions by reducing them all to a single category.</p>$SATQ$, $SATQ$<p>Which finding about mbaqanga and quan họ, if true, would most directly support Zheng&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"52218b89-2682-40f5-b6ee-c3b33cfdf493","content":"<p>Mbaqanga and quan họ developed independently of each other and have little in common musically.</p>"},{"id":"8bc8efe4-4f14-4144-8ba2-812c6e015598","content":"<p>Mbaqanga is significantly more popular in the English-speaking world than quan họ is.&nbsp;</p>"},{"id":"bddfe29c-ba48-498f-ad47-542a11ceef11","content":"<p>Mbaqanga and quan họ are now performed by a diverse array of musicians with no direct connections to South Africa or Vietnam.&nbsp;</p>"},{"id":"2781115c-10b9-4d9a-8d06-037febfbbbb0","content":"<p>Mbaqanga and quan họ are highly distinct from British and North American popular music genres but similar to each other.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["52218b89-2682-40f5-b6ee-c3b33cfdf493"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. Zheng&rsquo;s claim is that the idea of world music &ldquo;homogenizes&rdquo; (meaning makes similar) distinct kinds of music by reducing them to one category. In other words, Zheng thinks the concept of world music is a harmful oversimplification of diverse musical forms. To support this claim, we need evidence that these musical traditions are so different from one another that they should not fall into the same category. If it&rsquo;s true that mbaqanga and quan họ developed separately and have little in common musically, then it wouldn&rsquo;t make sense to lump them into the same category. </p><p>Choice B is incorrect. If true, this wouldn&rsquo;t affect the claim. To support the claim, we need evidence that these musical traditions are so different from one another that they should not fall into the same category. A difference in popularity doesn&rsquo;t necessarily mean that the two musical traditions shouldn&rsquo;t be categorized together: instead, we need to know if the music itself is similar or different. Choice C is incorrect. If true, this wouldn&rsquo;t affect the claim. To support the claim, we need evidence that these musical traditions are so different from each other that they should not fall into the same category. This choice doesn&rsquo;t do that. Choice D is incorrect. If true, this would actually weaken the claim. Zheng thinks it&rsquo;s reductive or oversimplifying to put distinct musical traditions into a single category. But if mbaqanga and quan họ are similar to each other, then it would make sense to put them in the same category. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-H002$SATQ$, $SATQ$$SATQ$, $SATQ$e5c6fafe-b299-47e1-897e-298c18221f1c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"09f9edb0","external_id":"35e63faf-cd1e-42e6-b544-7bf3b48941eb","vaultid":"d38b72e5-b606-432e-bd49-de10ee8e4a64","uId":"333bb4ef-d544-48c9-aea7-1f1133c1d6c7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In the 1980s, many musicians and journalists in the English-speaking world began to draw attention to music from around the globe&mdash;such as mbaqanga from South Africa and quan họ from Vietnam&mdash;that can&rsquo;t be easily categorized according to British or North American popular music genres, typically referring to such music as &ldquo;world music.&rdquo; While some scholars have welcomed this development for bringing diverse musical forms to prominence in countries where they&rsquo;d previously been overlooked, musicologist Su Zheng claims that the concept of world music homogenizes highly distinct traditions by reducing them all to a single category.</p>","stem":"<p>Which finding about mbaqanga and quan họ, if true, would most directly support Zheng&rsquo;s claim?</p>","answerOptions":[{"id":"52218b89-2682-40f5-b6ee-c3b33cfdf493","content":"<p>Mbaqanga and quan họ developed independently of each other and have little in common musically.</p>"},{"id":"8bc8efe4-4f14-4144-8ba2-812c6e015598","content":"<p>Mbaqanga is significantly more popular in the English-speaking world than quan họ is.&nbsp;</p>"},{"id":"bddfe29c-ba48-498f-ad47-542a11ceef11","content":"<p>Mbaqanga and quan họ are now performed by a diverse array of musicians with no direct connections to South Africa or Vietnam.&nbsp;</p>"},{"id":"2781115c-10b9-4d9a-8d06-037febfbbbb0","content":"<p>Mbaqanga and quan họ are highly distinct from British and North American popular music genres but similar to each other.</p>"}],"keys":["52218b89-2682-40f5-b6ee-c3b33cfdf493"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. Zheng&rsquo;s claim is that the idea of world music &ldquo;homogenizes&rdquo; (meaning makes similar) distinct kinds of music by reducing them to one category. In other words, Zheng thinks the concept of world music is a harmful oversimplification of diverse musical forms. To support this claim, we need evidence that these musical traditions are so different from one another that they should not fall into the same category. If it&rsquo;s true that mbaqanga and quan họ developed separately and have little in common musically, then it wouldn&rsquo;t make sense to lump them into the same category. </p><p>Choice B is incorrect. If true, this wouldn&rsquo;t affect the claim. To support the claim, we need evidence that these musical traditions are so different from one another that they should not fall into the same category. A difference in popularity doesn&rsquo;t necessarily mean that the two musical traditions shouldn&rsquo;t be categorized together: instead, we need to know if the music itself is similar or different. Choice C is incorrect. If true, this wouldn&rsquo;t affect the claim. To support the claim, we need evidence that these musical traditions are so different from each other that they should not fall into the same category. This choice doesn&rsquo;t do that. Choice D is incorrect. If true, this would actually weaken the claim. Zheng thinks it&rsquo;s reductive or oversimplifying to put distinct musical traditions into a single category. But if mbaqanga and quan họ are similar to each other, then it would make sense to put them in the same category. </p>","parenttemplatename":"OSP-KA-TXT-H002","parenttemplateid":"","templateclusterid":"e5c6fafe-b299-47e1-897e-298c18221f1c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376),
    ($SATQ$0a77c362$SATQ$, $SATQ$763708b4-8126-4bc6-9720-cce524db89ed$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;Aunt Sue&rsquo;s Stories&rdquo; is a 1926 poem by Langston Hughes. In the poem, the speaker indicates that the stories Aunt Sue tells are based on Aunt Sue&rsquo;s personal experiences, saying that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses a quotation from &ldquo;Aunt Sue&rsquo;s Stories&rdquo; to illustrate the claim?</p>$SATQ$, $SATQ$[{"id":"ca993e96-d9ff-40f2-aa2e-43756e2e2e9d","content":"<p>dark shadows &ldquo;cross and recross / Aunt Sue&rsquo;s stories.&rdquo;</p>"},{"id":"fc8ad0cf-79ac-4223-9c71-232b5976aab1","content":"<p>a listening child &ldquo;knows that Aunt Sue / Never got her stories out of any book at all, / But that they came / Right out of her own life.&rdquo;</p>"},{"id":"5e2fd9a4-cbc1-453c-a054-f063a911a1bf","content":"<p>the stories are told during &ldquo;Summer nights on the front porch.&rdquo;</p>"},{"id":"4207d4e1-1afa-4e1e-ae0a-d439110868f3","content":"<p>the people in the stories &ldquo;Mingle themselves softly / In the flow of old Aunt Sue&rsquo;s voice, / Mingle themselves softly.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["fc8ad0cf-79ac-4223-9c71-232b5976aab1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most effectively illustrates the speaker of the poem&rsquo;s claim that the stories Aunt Sue tells are based on Aunt Sue&rsquo;s personal experiences. In the quotation, the speaker conveys the listening child&rsquo;s point of view that Aunt Sue&rsquo;s stories originate from her personal experiences and are not taken from books or other external sources. The listening child explicitly contrasts two possible sources for Aunt Sue&rsquo;s stories: a book (whose potentially fictitious stories are implied to be written by someone else) or &ldquo;her own life.&rdquo; By having the child confidently assert that Aunt Sue &ldquo;never got her stories out of any book at all,&rdquo; the speaker indicates that Aunt Sue&rsquo;s stories are instead informed by her lived experiences.</p><p>Choice A is incorrect because it describes an element or image that recurs within Aunt Sue&rsquo;s stories rather than indicating that these stories have a real-life basis. The reference to dark shadows that &ldquo;cross and recross&rdquo; the stories functions as imagery on a literal, visual level and may also evoke figurative darkness, but this detail by itself doesn&rsquo;t suggest that the stories are based on Aunt Sue&rsquo;s personal experiences. Choice C is incorrect because it identifies the setting of Aunt Sue&rsquo;s storytelling rather than describing the real-life basis of the stories themselves. The quotation states that Aunt Sue tells her stories on &ldquo;summer nights on the front porch,&rdquo; which establishes when and where the storytelling occurs; however, no information is provided about the origins of the stories that Aunt Sue tells within this setting. Choice D is incorrect because it describes the movement or circulation of characters in the stories as Aunt Sue speaks rather than establishing that these stories have a real-life basis. The quotation primarily evokes the sounds of Aunt Sue&rsquo;s voice and the seemingly easy &ldquo;flow&rdquo; of this voice in her storytelling. Although the characters who &ldquo;mingle&hellip;in the flow of old Aunt Sue&rsquo;s voice&rdquo; are to some extent created or animated by her voice, no information is provided about the characters themselves or their relationship to Aunt Sue&rsquo;s actual experiences.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0a77c362","external_id":"763708b4-8126-4bc6-9720-cce524db89ed","vaultid":null,"uId":"3cac331d-57aa-4362-941a-5ed7c4106d2c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>&ldquo;Aunt Sue&rsquo;s Stories&rdquo; is a 1926 poem by Langston Hughes. In the poem, the speaker indicates that the stories Aunt Sue tells are based on Aunt Sue&rsquo;s personal experiences, saying that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses a quotation from &ldquo;Aunt Sue&rsquo;s Stories&rdquo; to illustrate the claim?</p>","answerOptions":[{"id":"ca993e96-d9ff-40f2-aa2e-43756e2e2e9d","content":"<p>dark shadows &ldquo;cross and recross / Aunt Sue&rsquo;s stories.&rdquo;</p>"},{"id":"fc8ad0cf-79ac-4223-9c71-232b5976aab1","content":"<p>a listening child &ldquo;knows that Aunt Sue / Never got her stories out of any book at all, / But that they came / Right out of her own life.&rdquo;</p>"},{"id":"5e2fd9a4-cbc1-453c-a054-f063a911a1bf","content":"<p>the stories are told during &ldquo;Summer nights on the front porch.&rdquo;</p>"},{"id":"4207d4e1-1afa-4e1e-ae0a-d439110868f3","content":"<p>the people in the stories &ldquo;Mingle themselves softly / In the flow of old Aunt Sue&rsquo;s voice, / Mingle themselves softly.&rdquo;</p>"}],"keys":["fc8ad0cf-79ac-4223-9c71-232b5976aab1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most effectively illustrates the speaker of the poem&rsquo;s claim that the stories Aunt Sue tells are based on Aunt Sue&rsquo;s personal experiences. In the quotation, the speaker conveys the listening child&rsquo;s point of view that Aunt Sue&rsquo;s stories originate from her personal experiences and are not taken from books or other external sources. The listening child explicitly contrasts two possible sources for Aunt Sue&rsquo;s stories: a book (whose potentially fictitious stories are implied to be written by someone else) or &ldquo;her own life.&rdquo; By having the child confidently assert that Aunt Sue &ldquo;never got her stories out of any book at all,&rdquo; the speaker indicates that Aunt Sue&rsquo;s stories are instead informed by her lived experiences.</p><p>Choice A is incorrect because it describes an element or image that recurs within Aunt Sue&rsquo;s stories rather than indicating that these stories have a real-life basis. The reference to dark shadows that &ldquo;cross and recross&rdquo; the stories functions as imagery on a literal, visual level and may also evoke figurative darkness, but this detail by itself doesn&rsquo;t suggest that the stories are based on Aunt Sue&rsquo;s personal experiences. Choice C is incorrect because it identifies the setting of Aunt Sue&rsquo;s storytelling rather than describing the real-life basis of the stories themselves. The quotation states that Aunt Sue tells her stories on &ldquo;summer nights on the front porch,&rdquo; which establishes when and where the storytelling occurs; however, no information is provided about the origins of the stories that Aunt Sue tells within this setting. Choice D is incorrect because it describes the movement or circulation of characters in the stories as Aunt Sue speaks rather than establishing that these stories have a real-life basis. The quotation primarily evokes the sounds of Aunt Sue&rsquo;s voice and the seemingly easy &ldquo;flow&rdquo; of this voice in her storytelling. Although the characters who &ldquo;mingle&hellip;in the flow of old Aunt Sue&rsquo;s voice&rdquo; are to some extent created or animated by her voice, no information is provided about the characters themselves or their relationship to Aunt Sue&rsquo;s actual experiences.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$0b634641$SATQ$, $SATQ$7920d9f7-7b71-430c-bc7c-ebcf5d8c1779$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg xmlns="http://www.w3.org/2000/svg" width="380" height="452.1007080078125" viewBox="0 0 380 452.1007080078125" role="img" aria-label="Bar graph titled Percent of Drawings Containing an Example of Each Animal Group. The horizontal axis is labeled Animal. 3 bars are shown. The vertical axis is labeled Percent of drawings. It ranges from 0 to 90 in increments of 10. Refer to long description."><g id="ed420550-79eb-48d4-af01-cd27cdd08afd" data-name="Layer 1"><defs>
