    </defs><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="96" x2="365" y2="96" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="96" x2="85.91999816894531" y2="96" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 102)" fill="#000000" font-size="19.84" font-family="Crimson Text">90</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="118.22222222222223" x2="365" y2="118.22222222222223" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="118.22222222222223" x2="85.91999816894531" y2="118.22222222222223" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 124.22222222222223)" fill="#000000" font-size="19.84" font-family="Crimson Text">80</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="140.44444444444446" x2="365" y2="140.44444444444446" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.91999816894531" y1="140.44444444444446" x2="85.91999816894531" y2="140.44444444444446" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(67.91999816894531 146.44444444444446)" fill="#000000" font-size="19.84" font-family="Crimson Text">70</text><line xmlns="http://www.w3.org/2000/svg" x1="79.91999816894531" y1="162.66666666666666" x2="365" y2="162.66666666666666" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="73.