777777777777\" height=\"22.22222222222222\" width=\"14.321864474903453\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(237.37949077606206 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">60&ndash;69</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"256.103219725869\" y=\"251.55555555555554\" height=\"44.44444444444444\" width=\"14.321864474903453\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"270.42508420077246\" y=\"296\" height=\"0\" width=\"14.321864474903453\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(280.3450842007725 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">70&ndash;79</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"299.0688131505794\" y=\"229.33333333333334\" height=\"66.66666666666666\" width=\"14.321864474903453\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"313.39067762548285\" y=\"273.77777777777777\" height=\"22.22222222222222\" width=\"14.321864474903453\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(323.31067762548287 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">80&ndash;89</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"342.0344065752898\" y=\"118.22222222222223\" height=\"177.77777777777777\" width=\"14.321864474903453\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"356.35627105019324\" y=\"229.33333333333334\" height=\"66.66666666666666\" width=\"14.321864474903453\" fill=\"#333333\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(366.27627105019326 315.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">90&ndash;100</text><text text-anchor=\"middle\" transform=\"translate(227.459490776062 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Number of Lizard Species by Average </text><text text-anchor=\"middle\" transform=\"translate(227.459490776062 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Percent of Maximal Speed Used When </text><text text-anchor=\"middle\" transform=\"translate(227.459490776062 72)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Pursuing Prey or Escaping Predators</text><text text-anchor=\"middle\" transform=\"translate(227.459490776062 385.117961730957)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Percent of maximal speed </text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"120.72218227386475\" y=\"402.27796173095703\" height=\"26.84\" width=\"213.47461700439453\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"127.72218227386475\" y=\"409.27796173095703\" height=\"12\" width=\"12\" fill=\"#B3B3B3\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(146.72218227386475 421.27796173095703)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">escaping</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"230.57458400726318\" y=\"409.27796173095703\" height=\"12\" width=\"12\" fill=\"#333333\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(249.57458400726318 421.27796173095703)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">pursuing</text></g></svg></figure><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for bar graph titled Number of Lizard Species by Average Percent of Maximal Speed Used When Pursuing Prey or Escaping Predators\"><ul>\n<li>For each data category, the following bars are shown:<br/>\n<ul>\n<li>escaping</li>\n<li>pursuing</li>\n</ul>\n</li>\n<li>The data for the 7 categories are as follows:<br/>\n<ul>\n<li>30&ndash;39 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 0 species</li>\n<li>pursuing: 1 species</li>\n</ul>\n</li>\n<li>40&ndash;49 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 0 species</li>\n<li>pursuing: 0 species</li>\n</ul>\n</li>\n<li>50&ndash;59 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 2 species</li>\n<li>pursuing: 1 species</li>\n</ul>\n</li>\n<li>60&ndash;69 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 1 species</li>\n<li>pursuing: 1 species</li>\n</ul>\n</li>\n<li>70&ndash;79 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 2 species</li>\n<li>pursuing: 0 species</li>\n</ul>\n</li>\n<li>80&ndash;89 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 3 species</li>\n<li>pursuing: 1 species</li>\n</ul>\n</li>\n<li>90&ndash;100 percent of maximal speed:<br/>\n<ul>\n<li>escaping: 8 species</li>\n<li>pursuing: 3 species</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul></div>\n<p>It may seem that the optimal strategy for an animal pursuing prey or escaping predators is to move at maximal speed, but the energy expense of exploiting full speed capacity can disfavor such a strategy even in escape contexts, as evidenced by the fact that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the graph to complete the text?</p>","answerOptions":[{"id":"dd95c9aa-658e-4a33-a0f1-5acb106801aa","content":"<p>most lizard species use about the same percentage of their maximal speed when escaping predation as they do when pursuing prey.</p>"},{"id":"64c8ead7-c0a1-4dd8-9375-f4595b979231","content":"<p>multiple lizard species move at an average of less than 90% of their maximal speed while escaping predation.</p>"},{"id":"b2d393e5-911e-4a05-8adb-4e7949048c13","content":"<p>more lizard species use, on average, 90%&ndash;100% of their maximal speed while escaping predation than use any other percentage of their maximal speed.</p>"},{"id":"ac6ab2c6-a249-40cd-b848-fa37a6bc5570","content":"<p>at least 4 lizard species use, on average, less than 100% of their maximal speed while pursuing prey.</p>"}],"keys":["64c8ead7-c0a1-4dd8-9375-f4595b979231"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it describes data from the graph that complete the text&rsquo;s discussion of lizard species&rsquo; use of maximal speed when escaping predators. According to the text, moving at maximal speed (the highest speed possible) requires so much energy that it is not always an effective strategy for animals, even when they are escaping predators. The graph displays data on the average percent of maximal speed used by lizard species while either escaping predators or pursuing prey. The graph categorizes the data for both pursuing and escaping by the number of species using 30%&ndash;39% of maximal speed, 40%&ndash;49% of maximal speed, 50%&ndash;59% of maximal speed, 60%&ndash;69% of maximal speed, 70%&ndash;79% of maximal speed, 80%&ndash;89% of maximal speed, and 90%&ndash;100% of maximal speed, respectively. In the graph, there is at least one species in each of the following percent categories for maximal speed while escaping predators: 50%&ndash;59%, 60%&ndash;69%, 70%&ndash;79%, and 80%&ndash;89%. Thus, the data in the graph show that multiple lizard species move at an average of less than 90% of their maximal speed while escaping predation.</p><p>Choice A is incorrect because the data in the graph isn&rsquo;t organized in such a way that a comparison of the percentage of maximal speed used when escaping predation with the percentage used when pursuing prey is possible at the level of individual species. Choice C is incorrect. It is true that in the graph, the percent category with the largest number of species using maximal speed while escaping predators is 90%&ndash;100% (8 species total). However, these data don&rsquo;t complete the text, which is concerned instead with how animals are discouraged from using maximal speed even when escaping predators because of the amount of energy required to use it. Choice D is incorrect because these data from the graph pertain to maximal speed while pursuing prey and therefore don&rsquo;t complete the text&rsquo;s discussion of lizard species&rsquo; use of maximal speed when escaping predators.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323046,"updateDate":1730147323046}$SATQ$::jsonb, 1730147323046, 1730147323046),
    ($SATQ$14189fbb$SATQ$, $SATQ$4e06110f-0c9b-48ea-88ab-a1004353ab6d$SATQ$::uuid, $SATQ$5a4d918d-f760-4e38-aa8e-9276d92a9562$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Having written the impassioned call to arms &ldquo;Letter to the Spanish Americans&rdquo; in 1791, Peruvian intellectual Juan Pablo Viscardo y Guzm&aacute;n is often considered a forerunner for the independence movements in Latin America. But Viscardo&rsquo;s role in history would have remained insignificant were it not for Venezuelan revolutionary Francisco de Miranda, who was handed the unpublished letter after Viscardo&rsquo;s death. Miranda not only helped circulate the letter, but his edits and footnotes to the text position Miranda as a central figure in the text&rsquo;s creation.</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"c762b6fc-5ebe-4369-aca2-7672f9870b9e","content":"<p>The original authorship of &ldquo;Letter to the Spanish Americans&rdquo; is disputed by contemporary historians.</p>"},{"id":"ecd4d1b7-2f6e-4b7a-acd1-8589dd28e07a","content":"<p>The majority of the most eloquently stated arguments in &ldquo;Letter to the Spanish Americans&rdquo; were written by Miranda.</p>"},{"id":"39d0572e-b5d9-4961-b1d0-f93bdc0010a2","content":"<p>Miranda played a crucial role in influencing the content and distribution of &ldquo;Letter to the Spanish Americans.&rdquo;&nbsp;</p>"},{"id":"6b772051-c79d-49c3-a4fd-b06e03ac7eba","content":"<p>&ldquo;Letter to the Spanish Americans&rdquo; persuaded many people in Latin America to pursue national independence.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["39d0572e-b5d9-4961-b1d0-f93bdc0010a2"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The text describes how Miranda circulated, edited, and added footnotes to &ldquo;Letter to the Spanish Americans,&rdquo; and it claims that the letter and its author would have &ldquo;remained insignificant&rdquo; if it weren&rsquo;t for Miranda&rsquo;s efforts. </p><p>Choice A is incorrect. The text only says that Viscardo wrote the letter and that Miranda edited it: it never suggests that the original authorship of the letter is up for debate. Choice B is incorrect. This contradicts the text. The text says that Miranda edited and footnoted the letter, but it identifies Viscardo as the letter&rsquo;s author. It also never identifies certain arguments as more eloquent than others. Choice D is incorrect. This is outside the scope of the text. The paragraph describes Miranda&rsquo;s role in the creation and distribution of the letter, but it doesn&rsquo;t get into the effects of the letter on other people. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-H008$SATQ$, $SATQ$$SATQ$, $SATQ$e456fcf9-8ba7-4159-a283-4616038471ae$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"14189fbb","external_id":"4e06110f-0c9b-48ea-88ab-a1004353ab6d","vaultid":"5a4d918d-f760-4e38-aa8e-9276d92a9562","uId":"4f773d7b-9ed0-42c8-9d52-7a2d53c3f944","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Having written the impassioned call to arms &ldquo;Letter to the Spanish Americans&rdquo; in 1791, Peruvian intellectual Juan Pablo Viscardo y Guzm&aacute;n is often considered a forerunner for the independence movements in Latin America. But Viscardo&rsquo;s role in history would have remained insignificant were it not for Venezuelan revolutionary Francisco de Miranda, who was handed the unpublished letter after Viscardo&rsquo;s death. Miranda not only helped circulate the letter, but his edits and footnotes to the text position Miranda as a central figure in the text&rsquo;s creation.</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"c762b6fc-5ebe-4369-aca2-7672f9870b9e","content":"<p>The original authorship of &ldquo;Letter to the Spanish Americans&rdquo; is disputed by contemporary historians.</p>"},{"id":"ecd4d1b7-2f6e-4b7a-acd1-8589dd28e07a","content":"<p>The majority of the most eloquently stated arguments in &ldquo;Letter to the Spanish Americans&rdquo; were written by Miranda.</p>"},{"id":"39d0572e-b5d9-4961-b1d0-f93bdc0010a2","content":"<p>Miranda played a crucial role in influencing the content and distribution of &ldquo;Letter to the Spanish Americans.&rdquo;&nbsp;</p>"},{"id":"6b772051-c79d-49c3-a4fd-b06e03ac7eba","content":"<p>&ldquo;Letter to the Spanish Americans&rdquo; persuaded many people in Latin America to pursue national independence.</p>"}],"keys":["39d0572e-b5d9-4961-b1d0-f93bdc0010a2"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The text describes how Miranda circulated, edited, and added footnotes to &ldquo;Letter to the Spanish Americans,&rdquo; and it claims that the letter and its author would have &ldquo;remained insignificant&rdquo; if it weren&rsquo;t for Miranda&rsquo;s efforts. </p><p>Choice A is incorrect. The text only says that Viscardo wrote the letter and that Miranda edited it: it never suggests that the original authorship of the letter is up for debate. Choice B is incorrect. This contradicts the text. The text says that Miranda edited and footnoted the letter, but it identifies Viscardo as the letter&rsquo;s author. It also never identifies certain arguments as more eloquent than others. Choice D is incorrect. This is outside the scope of the text. The paragraph describes Miranda&rsquo;s role in the creation and distribution of the letter, but it doesn&rsquo;t get into the effects of the letter on other people. </p>","parenttemplatename":"OSP-KA-CID-H008","parenttemplateid":"","templateclusterid":"e456fcf9-8ba7-4159-a283-4616038471ae","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$145da981$SATQ$, $SATQ$298fe3f3-a1cc-4f2d-9878-6e32ca1fa84c$SATQ$::uuid, $SATQ$d592ed55-864b-4c23-b036-04ca16d14132$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Effect of Paywall Introduction on Newspaper Companies&rsquo; Revenues</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Newspaper</th><th scope="col" style="text-align: center; vertical-align: bottom;">Total revenue change ($ in thousands)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Percentage change (%)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Newspaper size</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;"><em>Los Angeles Times</em></th><td style="text-align: center;">93,966</td><td style="text-align: center;">12.5</td><td>large</td></tr><tr><th scope="row" style="text-align: left;"><em>The New York Times</em></th><td style="text-align: center;">235,788</td><td style="text-align: center;">20</td><td>large</td></tr><tr><th scope="row" style="text-align: left;"><em>The Denver Post</em></th><td><span aria-hidden="true">&minus;3,765</span><span class="sr-only">negative 3,765</span></td><td><span aria-hidden="true">&minus;1</span><span class="sr-only">negative 1</span></td><td>small</td></tr><tr><th scope="row" style="text-align: left;"><em>Sun Sentinel</em></th><td><span aria-hidden="true">&minus;24,899</span><span class="sr-only">negative 24,899</span></td><td><span aria-hidden="true">&minus;11.9</span><span class="sr-only">negative 11.9</span></td><td>small</td></tr><tr><th scope="row" style="text-align: left;"><em>Chicago Tribune</em></th><td style="text-align: center;">94,492</td><td style="text-align: center;">19</td><td>large</td></tr></tbody></table></figure></p>
<p>Digital paywalls restrict access to online content to those with a paid subscription. In an investigation of the effect of paywalls on newspaper company revenues for print and digital subscriptions and advertising, Doug J. Chung and colleagues compared actual outcomes (with a paywall) to control estimates (without a paywall). The researchers concluded that introducing a paywall is generally more beneficial for larger newspapers, which have high circulation and tend to offer a substantial amount of unique online content.</p>$SATQ$, $SATQ$<p>Which choice best describes data from the table that support Chung and colleagues&rsquo; conclusion?</p>$SATQ$, $SATQ$[{"id":"3e0cceb7-885c-4805-a238-812d2a1192ca","content":"<p>The <em>Chicago Tribune</em> and the <em>Los Angeles Times</em> had similar total revenue changes, but the <em>Los Angeles Times</em> had a smaller percentage change.</p>"},{"id":"d3458851-2386-4cfd-b117-b0e1a86d2d60","content":"<p>The <em>Los Angeles Times</em> had a 12.5% revenue change, while the <em>Chicago Tribune</em> had a 19% revenue change.</p>"},{"id":"56dc15da-c741-4f2b-af41-5393bb23cf39","content":"<p><em>The</em> <em>New York Times</em> had a 20% revenue change, while the <em>Denver Post</em> had a <span aria-hidden=\"true\">&minus;1%</span><span class=\"sr-only\">negative 1%</span> revenue change.</p>"},{"id":"d596e42c-ceea-4d12-941a-812ad34bd96e","content":"<p><em>The Denver Post</em> had only a <span aria-hidden=\"true\">&minus;1%</span><span class=\"sr-only\">negative 1%</span> revenue change, which was the smallest percentage change of the selected companies.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["56dc15da-c741-4f2b-af41-5393bb23cf39"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The conclusion is that paywalls are more beneficial for large newspapers. This data supports that conclusion by comparing the revenue increase of a large newspaper to the revenue decrease of a small newspaper. </p><p>Choice A is incorrect. This choice doesn&rsquo;t support the conclusion. It doesn&rsquo;t include any small newspapers for comparison. Choice B is incorrect. This choice doesn&rsquo;t support the conclusion. It doesn&rsquo;t include any small newspapers for comparison. Choice D is incorrect. This choice doesn&rsquo;t support the conclusion. It doesn&rsquo;t include any large newspapers for comparison. </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-M001$SATQ$, $SATQ$$SATQ$, $SATQ$265ab08e-df0b-4daa-b55a-33200fe842e4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"145da981","external_id":"298fe3f3-a1cc-4f2d-9878-6e32ca1fa84c","vaultid":"d592ed55-864b-4c23-b036-04ca16d14132","uId":"c3b54a89-cad1-4170-9249-4a22175c2a92","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Effect of Paywall Introduction on Newspaper Companies&rsquo; Revenues</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Newspaper</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Total revenue change ($ in thousands)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Percentage change (%)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Newspaper size</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\"><em>Los Angeles Times</em></th><td style=\"text-align: center;\">93,966</td><td style=\"text-align: center;\">12.5</td><td>large</td></tr><tr><th scope=\"row\" style=\"text-align: left;\"><em>The New York Times</em></th><td style=\"text-align: center;\">235,788</td><td style=\"text-align: center;\">20</td><td>large</td></tr><tr><th scope=\"row\" style=\"text-align: left;\"><em>The Denver Post</em></th><td><span aria-hidden=\"true\">&minus;3,765</span><span class=\"sr-only\">negative 3,765</span></td><td><span aria-hidden=\"true\">&minus;1</span><span class=\"sr-only\">negative 1</span></td><td>small</td></tr><tr><th scope=\"row\" style=\"text-align: left;\"><em>Sun Sentinel</em></th><td><span aria-hidden=\"true\">&minus;24,899</span><span class=\"sr-only\">negative 24,899</span></td><td><span aria-hidden=\"true\">&minus;11.9</span><span class=\"sr-only\">negative 11.9</span></td><td>small</td></tr><tr><th scope=\"row\" style=\"text-align: left;\"><em>Chicago Tribune</em></th><td style=\"text-align: center;\">94,492</td><td style=\"text-align: center;\">19</td><td>large</td></tr></tbody></table></figure></p>\n<p>Digital paywalls restrict access to online content to those with a paid subscription. In an investigation of the effect of paywalls on newspaper company revenues for print and digital subscriptions and advertising, Doug J. Chung and colleagues compared actual outcomes (with a paywall) to control estimates (without a paywall). The researchers concluded that introducing a paywall is generally more beneficial for larger newspapers, which have high circulation and tend to offer a substantial amount of unique online content.</p>","stem":"<p>Which choice best describes data from the table that support Chung and colleagues&rsquo; conclusion?</p>","answerOptions":[{"id":"3e0cceb7-885c-4805-a238-812d2a1192ca","content":"<p>The <em>Chicago Tribune</em> and the <em>Los Angeles Times</em> had similar total revenue changes, but the <em>Los Angeles Times</em> had a smaller percentage change.</p>"},{"id":"d3458851-2386-4cfd-b117-b0e1a86d2d60","content":"<p>The <em>Los Angeles Times</em> had a 12.5% revenue change, while the <em>Chicago Tribune</em> had a 19% revenue change.</p>"},{"id":"56dc15da-c741-4f2b-af41-5393bb23cf39","content":"<p><em>The</em> <em>New York Times</em> had a 20% revenue change, while the <em>Denver Post</em> had a <span aria-hidden=\"true\">&minus;1%</span><span class=\"sr-only\">negative 1%</span> revenue change.</p>"},{"id":"d596e42c-ceea-4d12-941a-812ad34bd96e","content":"<p><em>The Denver Post</em> had only a <span aria-hidden=\"true\">&minus;1%</span><span class=\"sr-only\">negative 1%</span> revenue change, which was the smallest percentage change of the selected companies.</p>"}],"keys":["56dc15da-c741-4f2b-af41-5393bb23cf39"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The conclusion is that paywalls are more beneficial for large newspapers. This data supports that conclusion by comparing the revenue increase of a large newspaper to the revenue decrease of a small newspaper. </p><p>Choice A is incorrect. This choice doesn&rsquo;t support the conclusion. It doesn&rsquo;t include any small newspapers for comparison. Choice B is incorrect. This choice doesn&rsquo;t support the conclusion. It doesn&rsquo;t include any small newspapers for comparison. Choice D is incorrect. This choice doesn&rsquo;t support the conclusion. It doesn&rsquo;t include any large newspapers for comparison. </p>","parenttemplatename":"OSP-KA-QUA-M001","parenttemplateid":"","templateclusterid":"265ab08e-df0b-4daa-b55a-33200fe842e4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959370,"updateDate":1691007959370}$SATQ$::jsonb, 1691007959370, 1691007959370),
    ($SATQ$156ff681$SATQ$, $SATQ$f88c0e77-479a-4c8d-996f-c9b7d9e730d3$SATQ$::uuid, $SATQ$9426a738-9d8c-47c7-a9a2-4c6b05562b8e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Many governments that regularly transfer money to individuals&mdash;to provide supplemental incomes for senior citizens, for example&mdash;have long done so electronically, but other countries typically have distributed physical money and have only recently developed electronic transfer infrastructure. Researchers studied the introduction of an electronic transfer system in one such location and found that recipients of electronic transfers consumed a different array of foods than recipients of physical transfers of the same amount did. One potential explanation for this result is that individuals conceive of and allocate funds in physical money differently than they conceive of and allocate funds in electronic form.&nbsp;</p>$SATQ$, $SATQ$<p>Which finding from the study, if true, would most directly weaken the potential explanation?</p>$SATQ$, $SATQ$[{"id":"663d1545-60f7-44a0-b9fa-070a976eaf9a","content":"<p>Recipients of electronic transfers typically spent their funds at a slower rate than recipients of physical transfers did.&nbsp;</p>"},{"id":"3b7b5e46-cdef-4f6f-aa14-68b02bff86b4","content":"<p>Nearly every recipient of an electronic transfer withdrew the entire amount in physical money shortly after receiving the transfer.</p>"},{"id":"b46d4d63-1f63-4619-9d59-bd4f12ac3005","content":"<p>Recipients of physical transfers tended to purchase food about as frequently as recipients of electronic transfers did.&nbsp;</p>"},{"id":"ac7906a4-7c2a-4500-a9eb-f4161e07db75","content":"<p>Some recipients of physical transfers received small amounts of money relatively frequently, while others received large amounts relatively infrequently.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["3b7b5e46-cdef-4f6f-aa14-68b02bff86b4"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This would weaken the explanation. If the recipients of electronic money immediately withdrew it all as physical money, then both kinds of recipients ended up spending physical money on food. So there must be some other explanation why those who initially received electronic money ate different kinds of food. </p><p>Choice A is incorrect. This wouldn&rsquo;t weaken the explanation. If anything, it actually supports it: it demonstrates that recipients of electronic money and recipients of physical money have different spending habits. Choice C is incorrect. This wouldn&rsquo;t weaken the explanation. The explanation we&rsquo;re testing this choice against is about the way that people might &ldquo;conceive of and allocate&rdquo; physical and electronic funds differently. This choice only focuses on the timing, not what they spend the money on. Choice D is incorrect. This would have no impact on the explanation. It doesn&rsquo;t tell us anything about possible differences between the spending habits of those who spend physical money and those who spend money electronically. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-H003$SATQ$, $SATQ$$SATQ$, $SATQ$97b87aa2-ca19-417b-9ec2-24713880dbd6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"156ff681","external_id":"f88c0e77-479a-4c8d-996f-c9b7d9e730d3","vaultid":"9426a738-9d8c-47c7-a9a2-4c6b05562b8e","uId":"528bee5c-eda6-4ee5-89c4-767405256b1f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Many governments that regularly transfer money to individuals&mdash;to provide supplemental incomes for senior citizens, for example&mdash;have long done so electronically, but other countries typically have distributed physical money and have only recently developed electronic transfer infrastructure. Researchers studied the introduction of an electronic transfer system in one such location and found that recipients of electronic transfers consumed a different array of foods than recipients of physical transfers of the same amount did. One potential explanation for this result is that individuals conceive of and allocate funds in physical money differently than they conceive of and allocate funds in electronic form.&nbsp;</p>","stem":"<p>Which finding from the study, if true, would most directly weaken the potential explanation?</p>","answerOptions":[{"id":"663d1545-60f7-44a0-b9fa-070a976eaf9a","content":"<p>Recipients of electronic transfers typically spent their funds at a slower rate than recipients of physical transfers did.&nbsp;</p>"},{"id":"3b7b5e46-cdef-4f6f-aa14-68b02bff86b4","content":"<p>Nearly every recipient of an electronic transfer withdrew the entire amount in physical money shortly after receiving the transfer.</p>"},{"id":"b46d4d63-1f63-4619-9d59-bd4f12ac3005","content":"<p>Recipients of physical transfers tended to purchase food about as frequently as recipients of electronic transfers did.&nbsp;</p>"},{"id":"ac7906a4-7c2a-4500-a9eb-f4161e07db75","content":"<p>Some recipients of physical transfers received small amounts of money relatively frequently, while others received large amounts relatively infrequently.</p>"}],"keys":["3b7b5e46-cdef-4f6f-aa14-68b02bff86b4"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This would weaken the explanation. If the recipients of electronic money immediately withdrew it all as physical money, then both kinds of recipients ended up spending physical money on food. So there must be some other explanation why those who initially received electronic money ate different kinds of food. </p><p>Choice A is incorrect. This wouldn&rsquo;t weaken the explanation. If anything, it actually supports it: it demonstrates that recipients of electronic money and recipients of physical money have different spending habits. Choice C is incorrect. This wouldn&rsquo;t weaken the explanation. The explanation we&rsquo;re testing this choice against is about the way that people might &ldquo;conceive of and allocate&rdquo; physical and electronic funds differently. This choice only focuses on the timing, not what they spend the money on. Choice D is incorrect. This would have no impact on the explanation. It doesn&rsquo;t tell us anything about possible differences between the spending habits of those who spend physical money and those who spend money electronically. </p>","parenttemplatename":"OSP-KA-TXT-H003","parenttemplateid":"","templateclusterid":"97b87aa2-ca19-417b-9ec2-24713880dbd6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376)
